ANNOTATIONS = [
    (20, 'after_block', r'''捕获模块命名空间而不是函数本身：spyOn() 变异的是模块对象，`voiceNs.useVoice(...)` 这样写才能在 spy 装晚于本模块加载时仍然解析到 spy（测试顺序独立性）。整段是 DCE 条件 import——VOICE_MODE 特性关闭时给一个恒 idle 的 stub，useVoice 那 1,100 行根本不进 bundle。'''),
    (39, 'before', r'''RAPID_KEY_GAP_MS = 120ms。终端 auto-repeat 每 30-80ms 一发；120ms 盖住抖动，同时把正常打字速度（100-300ms 间隔）排除在外——这是「按住」与「连打」的分界线。'''),
    (46, 'after', r'''组合键首按 fallback 与 useVoice.ts 的 FIRST_PRESS_FALLBACK_MS 必须一致（2s）：等的是 OS 初始重复延迟的上限，不是重复速率，对不齐会让长按组合键碎成两个会话。'''),
    (51, 'after', r'''HOLD_THRESHOLD = 5：裸字符绑定（空格、v）需要 5 次快速连击才激活——单发一个空格可能只是正常打字。组合键无此门槛，首按即激活。'''),
    (54, 'after', r'''WARMUP_THRESHOLD = 2：第 2 次快速击键开始显示预热反馈，用户知道「系统 recognition 到我在按住了」。'''),
    (60, 'after_block', r'''matchesKeyboardEvent 的存在本身是个迁移事故标本：onKeyDown 迁移（#23524）后 input 流变成了 KeyboardEvent，其 key 是归一化名字（space/f9），而 legacy matchesKeystroke 假设的是 useInput 的原始 input——组合键和 f 键在迁移后静默失配。这个函数是新旧两条路的适配层。'''),
    (73, 'after', r'''meta 字段把 alt|option 折叠在一起（终端限制：esc 前缀序列无法区分），ParsedKeystroke 里 alt 和 meta 本就是同一个东西的别名。'''),
    (86, 'after', r'''DEFAULT_VOICE_KEYSTROKE 只在完全没有 KeybindingProvider 时用（headless/测试）。provider 存在但查不到 = 用户显式解绑或改绑了，此时 fallback 到空格会挑一个死的或冲突的键——不 second-guess 用户。'''),
    (117, 'after', r'''对外契约：stripTrailing 返回剥离后剩余的尾部字符数，resetAnchor 撤销锚点，interimRange 给 UI 变暗用。'''),
    (138, 'after', r'''lastSetInputRef 是全文件唯一的写入守卫，也是唯一能正确处理「空前缀+空后缀」的方案：startsWith('')/endsWith('') 会真空通过，length 比较分不清「被清空」和「从未设置」。两条写入路径（锚点、interim）都维护它，用户一提交或编辑，两个回调都能发现并 bail。'''),
    (151, 'after_block', r'''stripTrailing 的两个调用场景：预热期清泄漏（监听器顺序不保证，文本输入可能先跑）+ 激活时剥掉故意放行的字符并捕获锚点。调用方传精确的期望剥离数，边界上用户已有的字符（hav 里的 v）才不会被误剥。'''),
    (164, 'after', r'''全角空格 U+3000 也要数：CJK 输入法为同一个物理空格键发的是全角空格。U+3000 是 BMP 单代码单元，索引与 beforeCursor 对齐，可以直接扫。'''),
    (171, 'after', r'''gap space 的用途：锚定时若后缀非空白，插一个缝空格让波形光标停在缝上而不是盖住后缀首字母。interim effect 维护同样的五段结构（前缀+引导+interim+尾随+后缀），转写文字一到位，缝就无缝长进文本里。'''),
    (180, 'after', r'''anchor=true 时总是覆盖：上次激活失败（voiceState 停在 idle）时 cleanup effect 没触发，旧锚点还在输入里——不覆盖就会把转录插到陈旧位置。'''),
    (198, 'after', r'''注意 newValue === prev && stripCount === 0 时直接返回不碰状态：没有变化就不触发 React 更新，录音中的高频防御性剥离因此零渲染。'''),
    (205, 'after_block', r'''resetAnchor 补的是 cleanup effect 的盲区：那个 effect 只在 voiceState 转换时触发，激活失败（voiceState 原地不动）时到不了——没有这个函数，缝空格和陈旧 ref 会一直留在输入框里。'''),
    (224, 'after', r'''三个 voice selector 都用 feature() 编译期常量做条件调用——biome 的 useHookAtTopLevel 会误报，因为常量在编译后只剩一支，hook 顺序稳定。useVoiceEnabled 内部把 auth 半边 memoize 在 authVersion 上，渲染循环不会冷启 keychain 子进程。'''),
    (248, 'after', r'''focus 模式的锚点在这里设（录音由终端焦点拉起，没有 stripTrailing 可调）；回 idle 时三个 ref 一起清。'''),
    (263, 'after', r'''提交竞态第一处：voicePrefixRef 要到 voiceState→idle 才清，所以 CloseStream 之后、WS 关闭之前的 processing 窗口里，迟到的 refined TranscriptText 还会尝试重填一个已被用户清空的输入框。'''),
    (280, 'after', r'''interim effect 的间距逻辑：不能 gate on voiceInterimTranscript.length——最终文本就位后 interim 清空，那时前缀和后缀之间的缝空格还必须保持。'''),
    (293, 'after', r'''提交竞速第二处：这里不能改用 text.length 比较——ASR  routinely 给最终稿加标点和修正，最终比 interim 长是常态，长度差会误判。'''),
    (310, 'after', r'''最后一步把本次转写并进 prefix：focus 模式连续转写时，下一段接在这段后面追加，而不是互相覆盖。'''),
    (324, 'after', r'''focusMode: false——这个 useVoice 实例只管按住说话；焦点驱动录音走另一个挂载点。onError 统一转通知（voice-error key，10s 自动消失）。'''),
    (340, 'after', r'''interimRange 给 UI 把「还没定稿的转写文字」画成暗色：起止点算法与插入逻辑严格同构，差一个字符暗色区域就会漂移。'''),
    (373, 'before', r'''按住说话激活器。设计分两种绑定类型：组合键（meta+k/ctrl+x/alt+v）首按即激活、无流透无剥离——组合键不可能被误打；裸字符（空格/v）要 5 连击，前 2 发放行进去当正常打字。已知坏例：modifier+space（NUL 被解析成 ctrl+backtick）和 chord（离散序列，没有按住概念），绑定校验时警告。'''),
    (404, 'after_block', r'''查找 voice:pushToTalk 绑定：正序迭代 last-wins（与 resolver 一致）——后一条 Chat 绑定把同一个 chord 改成 null 或别的动作，语音绑定作废返回 null，用户显式关掉就不救。context 过滤是必须的：空格在 Settings/Confirmation/Plugin 里也绑着（select:accept），不过滤会把默认值误杀。'''),
    (429, 'after', r'''bareChar 判定：单字符 + 无任何修饰键。这类绑定要处理「终端把 N 次 auto-repeat 合并成一个输入事件」（vvv），组合键则每次重复一个事件、不插文字。'''),
    (447, 'after', r'''四个 ref 分工：rapidCount 连击计数、charsInInput 故意放行数、recordingFloor 录音期防御剥离的地板、isHoldActive 区分按住录音与焦点录音。'''),
    (453, 'before', r'''离开 recording 立刻重置全部 hold 状态：物理按住结束在 auto-repeat 停止（状态进 processing），若把 ref 留到 processing 之后，用户边等转写边打的字会被全吞掉。'''),
    (479, 'after', r'''PromptInput 不是合法转录目标时的两条路径（#33556）：!isActive 是本地 jsx 命令藏了输入框但没注册 overlay（/install-github-app、/plugin）；isModalOverlayActive 是 overlay 拿了焦点。两条都要放行，否则按键被吞进陈旧 ref。'''),
    (484, 'after', r'''null = 用户用绑定覆盖显式关掉了按住说话。要开关功能本身用 /voice，不要在这里 fallback。'''),
    (500, 'after', r'''合并 auto-repeat 的处理：vvv 这种一次事件多个字符，除了首字符匹配还要验证整体是同一字符的重复——否则 vvvX 会被当成 v 的连击。快速路径上任何非绑定字符零分配直接 bail。'''),
    (515, 'before', r'''吞键双保险：isHoldActive 说明这次录音是按键拉起的，currentVoiceState 从 store 同步读——voiceHandleKeyEvent 没能切换状态（模块没加载、流不可用）时不会永久吞键。焦点录音中按键正常放行。'''),
    (541, 'after', r'''非按住录音（焦点模式）进行中：组合键吞掉但不重激活——stripTrailing(0,{anchor:true}) 会用 interim 文本覆盖 voicePrefixRef，下次 interim 更新就把转写插两遍（#22144 之前轻点一下就中招）。裸字符无条件放行：焦点录音时用户可能在打字。'''),
    (552, 'before', r'''激活分支刻意排在预热分支之前：同一 tick 里两个 strip 调用都会读到陈旧的 inputValueRef，第二个会少剥。组合键首按即激活，没有阈值问题。'''),
    (601, 'after', r'''激活后同步回检 store：voice 没能离开 idle（模块没加载/流不可用/enabled 陈旧）就清 isHoldActive + resetAnchor——不清的话后续焦点录音会继承陈旧的按住状态乱吞键。锚点反正总会被覆盖，这里撤销的是 gap 空格。'''),
    (620, 'after', r'''预热分支：countBefore 让跨过阈值的那一发仍然放行（终端批量合并时一个事件带多个字符）。floor 保护故意放行的字符，防御性剥离只清泄漏。'''),
    (646, 'after', r'''120ms 无后续快速击键就整体复位（连击计数、放行计数、预热 UI）。setTimeout 额外参数把三个 ref 和 setVoiceState 全传进去——不靠闭包捕获，避免陈旧值。'''),
    (652, 'after_block', r'''向后兼容桥：REPL.tsx 还没把 handleKeyDown 接到 Box onKeyDown 上，暂时用 useInput 订阅，把 InputEvent 适配成 KeyboardEvent。TODO 标记了迁移后删除。'''),
    (659, 'before', r'''这里必须再转发一次 stopImmediatePropagation：handleKeyDown 停掉的是适配出来的 KeyboardEvent，而 emitter 检查的是原始 InputEvent——不转发，文本输入的 useInput 监听器照样收到，按住空格就漏进提示框了。'''),
    (676, 'after', r'''临时 shim：让现有 JSX 调用方（VoiceKeybindingHandler 组件）继续编译，本体已经迁到 hook 形态。'''),
]
